DROP TRIGGER IF EXISTS _emdash_fts_design_update;
CREATE TRIGGER _emdash_fts_design_update AFTER UPDATE ON ec_design BEGIN
  INSERT INTO _emdash_fts_design(_emdash_fts_design, rowid, id, locale, title, summary, content) VALUES ('delete', OLD.rowid, OLD.id, OLD.locale, OLD.title, OLD.summary, OLD.content);
  INSERT INTO _emdash_fts_design(rowid, id, locale, title, summary, content) VALUES (NEW.rowid, NEW.id, NEW.locale, NEW.title, NEW.summary, NEW.content);
END;
DROP TRIGGER IF EXISTS _emdash_fts_design_delete;
CREATE TRIGGER _emdash_fts_design_delete AFTER DELETE ON ec_design BEGIN
  INSERT INTO _emdash_fts_design(_emdash_fts_design, rowid, id, locale, title, summary, content) VALUES ('delete', OLD.rowid, OLD.id, OLD.locale, OLD.title, OLD.summary, OLD.content);
END;
